customCSS:
.t, .history { color: #758094; }
.join { color: #a0c980; }
.part, .quit { color: #758094; }
.kick, .error { color: #ec7279; }
.notice { color: #deb974; }
.action { color: #d38aea; }
.mode, .nick, .topic, .server { color: #5dbbc1; }
.highlight { color: #c5cdd9; background-color: #3b3e48; border-left: 3px solid #d38aea; padding-left: 8px; }
.reply { color: #758094; border-left: 2px solid #6cb6eb; padding-left: 6px; }
.oper { color: #2c2e34; background-color: #deb974; }
.reactions { color: #6cb6eb; background-color: #363944; }
.card { background-color: #363944; border-color: #758094; }
.card-title { color: #6cb6eb; }
.card-desc { color: #758094; }
.daychange { color: #758094; border-color: #363944; }
